using namespace std;

const int MAXN = 2010;               // maximum number of nodes
const int INF = 0x3f3f3f;           // define the value of infinity
int maps[MAXN][MAXN];               // adjacency matrix
int dist[MAXN], vis[MAXN];          // distance and visited array
int n;                               // number of edges

void Init(int m) {                   // initialization function
    for(int i = 0; i <= m; i++) 
        for(int j = 0; j <= m; j++) 
            maps[i][j] = (i == j) ? 0 : INF; 
}

void dij(int s, int m) {             // dijkstra function
    for(int i = 0; i <= m; i++) 
        dist[i] = maps[s][i];
    fill(vis, vis + m + 1, 0);
    vis[s] = 1;

    for(int i = 0; i <= m; i++) {
        int Min = INF, index = -1;
        for(int j = 0; j <= m; j++) {
            if (!vis[j] && dist[j] < Min) {
                Min = dist[j];
                index = j;
            }
        }
        if (index == -1) continue;
        vis[index] = 1;

        for(int j = 0; j <= m; j++) {
            if (!vis[j] && dist[j] > Min + maps[index][j])
                dist[j] = Min + maps[index][j];
        }
    }
}

