    int a, b, c, Max, index, sum;
    while(scanf("%d", &n), n) {
        Init(1100);
        Max = -1;
        for(int i = 1; i <= n; i++) {
            scanf("%d%d%d", &a, &b, &c);
            maps[a][b] = maps[b][a] = min(maps[a][b], c);
            Max = max(Max, a);
            Max = max(Max, b);
        }
        sum = INF;
        for(int i = 0; i <= Max; i++) {
            dij(i, Max);
            int s = 0;
            for(int j = 0; j <= Max; j++)
                s += dist[j];
            if(s < sum) {
                index = i;
                sum = s;
            }
        }
        printf("%d %d\n", index, sum);
    }
    return 0;
}

