int shortestDistances[N], visitedVertices[N];

void Initialize(int matrixSize) {
    for(int i=0; i<=matrixSize; i++)
        for(int j=0; j<=matrixSize; j++)
            adjacencyMatrix[i][j]=i==j ? 0 : INF;
}

void Dijkstra(int sourceVertex, int matrixSize) {
    for(int i=0; i<=matrixSize; i++)
        shortestDistances[i]=adjacencyMatrix[sourceVertex][i];
    memset(visitedVertices, 0, sizeof(visitedVertices));
    visitedVertices[sourceVertex]=1;

    for(int i=0; i<=matrixSize; i++) {
        int minimumDistance=INF, index=-1;
        for(int j=0; j<=matrixSize; j++) {
            if(!visitedVertices[j]&&shortestDistances[j]<minimumDistance) {
                minimumDistance=shortestDistances[j];
                index=j;
            }
        }
        if(index==-1) continue;
        visitedVertices[index]=1;
        for(int j=0; j<=matrixSize; j++) {
            if(!visitedVertices[j]&&shortestDistances[j]>minimumDistance+adjacencyMatrix[index][j])
                shortestDistances[j]=minimumDistance+adjacencyMatrix[index][j];
        }
    }
}

