using namespace std;

typedef long long LL;
#define N 2010
#define INF 0x3f3f3f

int numberOfVertices;
int adjacencyMatrix[N][N];
int shortestDistances[N], visitedVertices[N];

void Initialize(int matrixSize) {
    for(int i=0; i<=matrixSize; i++)
        for(int j=0; j<=matrixSize; j++)
            adjacencyMatrix[i][j]=i==j ? 0 : INF;
}

void Dijkstra(int sourceVertex, int matrixSize) {
    for(int i=0; i<=matrixSize; i++)
        shortestDistances[i]=adjacencyMatrix[sourceVertex][i];
    memset(visitedVertices, 0, sizeof(visitedVertices));
    visitedVertices[sourceVertex]=1;

    for(int i=0; i<=matrixSize; i++) {
        int minimumDistance=INF, index=-1;
        for(int j=0; j<=matrixSize; j++) {
            if(!visitedVertices[j]&&shortestDistances[j]<minimumDistance) {
                minimumDistance=shortestDistances[j];
                index=j;
            }
        }
        if(index==-1) continue;
        visitedVertices[index]=1;
        for(int j=0; j<=matrixSize; j++) {
            if(!visitedVertices[j]&&shortestDistances[j]>minimumDistance+adjacencyMatrix[index][j])
                shortestDistances[j]=minimumDistance+adjacencyMatrix[index][j];
        }
    }
}

int main() {
    int vertexA, vertexB, edgeCost, maximumVertex, index, totalCost;
    while(scanf("%d", &numberOfVertices), numberOfVertices) {
        Initialize(1100);
        maximumVertex=-1;
        for(int i=1; i<=numberOfVertices; i++) {
            scanf("%d%d%d", &vertexA, &vertexB, &edgeCost);
            adjacencyMatrix[vertexA][vertexB]=adjacencyMatrix[vertexB][vertexA]=min(adjacencyMatrix[vertexA][vertexB], edgeCost);
            maximumVertex=max(maximumVertex, vertexA);
            maximumVertex=max(maximumVertex, vertexB);
        }
        int totalDistance;
        totalCost=INF;
        for(int i=0; i<=maximumVertex; i++) {
            Dijkstra(i, maximumVertex);
            totalDistance=0;
            for(int j=0; j<=maximumVertex; j++)
                totalDistance+=shortestDistances[j];
            if(totalDistance<totalCost) {
                index=i;
                totalCost=totalDistance;
            }
        }
        printf("%d %d\n", index, totalCost);
    }
    return 0;
}

